		// Keep a duplicate-bearing stream for the reopened, unknown-size native bulk path. A Set first load
		// preserves its known size through SailSourceConnection and admits prepared indexes on the cleared store.
		List<Statement> input = new ArrayList<>(payload.size() * 2);
		input.addAll(payload);
		input.addAll(payload);
		Map<Value, Long> ids;
		int initialQueuedOperations;
		int initialResizeChecks;
		int duplicateQueuedOperations;
