	private int maximumNativeBatches(int statementCount) {
		return (statementCount + LmdbSailStore.INITIAL_BULK_OPERATION_CAPACITY - 1)
				/ LmdbSailStore.INITIAL_BULK_OPERATION_CAPACITY;
	}

	private LmdbStore store(boolean inline) {
		return new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,posc,ospc,psoc")
				.setTripleTermIndexes("spoc,cspo")
				.setInlineLiterals(inline)
				.setBulkOperationSize(4096)
				.setValueDBSize(64L * 1024 * 1024)
				.setTripleDBSize(128L * 1024 * 1024)
				.setDirectAdjacencyEnabled(false)
				.setAutoGrow(true));
	}

	private List<Value> objects() {
		List<Value> result = new ArrayList<>();
		result.add(VF.createLiteral("+0007", XSD.INTEGER));
		result.add(VF.createLiteral("007.00", XSD.DECIMAL));
		result.add(VF.createLiteral("language spelling", "eN-GB"));
		for (String fraction : List.of("", ".0", ".00", ".000", ".037")) {
			result.add(VF.createLiteral("2026-10-02T12:37:00" + fraction + "Z", XSD.DATETIME));
		}
		result.add(LONG_LITERAL);
		result.add(VF.createIRI("urn:legacy-bulk:hashed:" + "abcdef".repeat(2048)));
		result.add(VF.createBNode("legacy-bulk-object"));
		result.add(OUTER);
		return result;
	}

	private Model payload(List<Value> objects) {
		Model result = new LinkedHashModel();
		for (int i = 0; i < ROW_COUNT; i++) {
			result.add(VF.createIRI("urn:legacy-bulk:row:" + i), PREDICATE, objects.get(i % objects.size()),
					i % 2 == 0 ? VF.createBNode("legacy-bulk-context") : null);
		}
		return result;
	}

	private void assertRows(LmdbStore store, RepositoryConnection connection, Model expected) throws Exception {
		assertThat(connection.size()).isEqualTo(expected.size());
		assertThat(connection.getNamespace("legacyBulk")).isEqualTo("urn:legacy-bulk:");
		Model actual = new LinkedHashModel();
		try (var rows = connection.getStatements(null, null, null, false)) {
			while (rows.hasNext()) {
				Statement statement = rows.next();
				assertThat(expected.contains(statement)).isTrue();
				actual.add(statement);
			}
		}
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		for (long entries : store.getBackingStore().explicitIndexEntryCounts().values()) {
			assertThat(entries).isEqualTo(expected.size());
		}
	}

	private Map<Value, Long> captureIds(LmdbStore store, List<Value> objects) throws Exception {
		Map<Value, Long> result = new HashMap<>();
		ValueStore values = (ValueStore) store.getValueFactory();
		List<Value> terms = new ArrayList<>(objects);
		terms.addAll(List.of(INNER, LEAF_SUBJECT, OUTER_OWNER, PREDICATE,
				VF.createBNode("legacy-bulk-context")));
		for (Value term : terms) {
			long id = values.getId(term);
			assertThat(id).isNotEqualTo(LmdbValue.UNKNOWN_ID);
			assertThat(ValueIds.isCoreLiteralReference(id)).isFalse();
			result.put(term, id);
			assertTerm(values.getValue(id), term);
		}
		return result;
	}

	private void assertIds(LmdbStore store, Map<Value, Long> ids) throws Exception {
		ValueStore values = (ValueStore) store.getValueFactory();
		for (Map.Entry<Value, Long> entry : ids.entrySet()) {
			assertThat(values.getId(entry.getKey())).isEqualTo(entry.getValue());
			assertTerm(values.getValue(entry.getValue()), entry.getKey());
		}
	}

	private void assertTerm(Value actual, Value expected) {
		assertThat(actual).isEqualTo(expected);
		if (expected instanceof Literal literal) {
			Literal decoded = (Literal) actual;
			assertThat(decoded.getLabel()).isEqualTo(literal.getLabel());
			assertThat(decoded.getLanguage()).isEqualTo(literal.getLanguage());
			assertThat(decoded.getDatatype()).isEqualTo(literal.getDatatype());
		} else if (expected instanceof TripleTerm triple) {
			TripleTerm decoded = (TripleTerm) actual;
			assertTerm(decoded.getSubject(), triple.getSubject());
			assertTerm(decoded.getPredicate(), triple.getPredicate());
			assertTerm(decoded.getObject(), triple.getObject());
		}
	}

	private Map<Long, Long> readReferenceCounts() throws Exception {
		long environment;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
		}
		try {
			E(mdb_env_set_maxdbs(environment, 32));
			E(mdb_env_open(environment, directory.resolve("values").toString(), MDB_NOTLS | MDB_RDONLY, 0664));
			return LmdbUtil.readTransaction(environment, (stack, transaction) -> {
				Map<Long, Long> result = new HashMap<>();
				int database = LmdbUtil.openDatabaseWithTxn(transaction, "ref_counts", 0);
				PointerBuffer handle = stack.mallocPointer(1);
				E(mdb_cursor_open(transaction, database, handle));
				long cursor = handle.get(0);
				try {
					MDBVal key = MDBVal.calloc(stack);
					MDBVal value = MDBVal.calloc(stack);
					int rc = mdb_cursor_get(cursor, key, value, MDB_FIRST);
					while (rc != MDB_NOTFOUND) {
						E(rc);
						ByteBuffer encoded = key.mv_data();
						byte prefix = encoded.get();
						if (prefix == ValueStoreRecordCodec.ID_KEY) {
							result.put(Varint.readUnsigned(encoded), Varint.readUnsigned(value.mv_data()));
						}
						rc = mdb_cursor_get(cursor, key, value, MDB_NEXT);
					}
				} finally {
					mdb_cursor_close(cursor);
				}
				return result;
			});
		} finally {
			mdb_env_close(environment);
		}
	}

	private void writeProtocolProperties(boolean inline) throws Exception {
		Properties properties = new Properties();
		properties.setProperty("version", "2");
		properties.setProperty("inline-literals", Boolean.toString(inline));
		properties.setProperty("triple-indexes", "spoc,posc,ospc,psoc");
		properties.setProperty("triple-term-indexes", "spoc,cspo");
		properties.setProperty("external-owner.keep", "original value");
		try (OutputStream output = Files.newOutputStream(directory.resolve("store.properties"))) {
			properties.store(output, "protocol-v2 batch fixture");
		}
	}

	private static Stream<Arguments> legacyCases() {
		return Stream.of(Arguments.of(false, false), Arguments.of(true, false),
				Arguments.of(false, true), Arguments.of(true, true));
	}
